//static uint8_t bma_array[4000];   //- для проверки визуально в отладчике правильно ли записался файл конфигурации
uint16_t ret;
uint32_t flag_err = 0;
  

//------------------------------------------------------------------------------
//- Инициализация BMP456
//------------------------------------------------------------------------------
void BMA456_init()
{
  CS_BMA456 = 0;                  //- дёрнуть ножкой CS для переключения с I2C на SPI интерфейс
  for(int i=0; i<25; i++) {;}
  CS_BMA456 = 1;
  for(int i=0; i<25; i++) {;}

  //- прочитать идентификатор чипа, должен быть 0x16
  Ecuinfo.params.BMA456.bma456_id = (uint8_t)BMA456_ReadReg(CHIP_ID);
  if(Ecuinfo.params.BMA456.bma456_id != 0x16)   flag_err |= ERR_BMA456_ChipID;

  //- отключить расширенный режим энергосбережения
  BMA456_WriteReg(PWR_CONF, 0x02);

  //- задержка не менее 450 мкс
  for(int i=0; i<0x2000; i++)  {;}     //- до 255 -> 22мкс, 0x2000 -> 680мкс, для SYSCLK=72 МГц

  BMA456_WriteReg(INIT_CTRL, 0x00);   //- перейти в режим инициализации (доступа к конфигурационному файлу в регистре FEATURES_IN)

  //- записать файл конфигурации в пакетном режиме
  CS_BMA456 = 0;
  while(SPI1->STS_B.TXBEF == 0)   {;}     SPI1->DATA = FEATURES_IN;     //- команда записи в регистр FEATURES_IN
  while(SPI1->STS_B.RXBNEF == 0)  {;}     ret = SPI1->DATA;
  
  for(int i=0; i<sizeof(bma456_an_config_file); i++)
  {
    while(SPI1->STS_B.TXBEF == 0)   {;}     SPI1->DATA = bma456_an_config_file[i];
    while(SPI1->STS_B.RXBNEF == 0)  {;}     ret = SPI1->DATA;
  }
  while(SPI1->STS_B.BUSYF == 1)   {;}    CS_BMA456 = 1;
  for(int i=0; i<255; i++) {;}
  
  //- проверка записанного файла конфигурации
  CS_BMA456 = 0;
  while(SPI1->STS_B.TXBEF == 0)   {;}     SPI1->DATA = FEATURES_IN | 0x80;    //- команда: чтение из регистра FEATURES_IN
  while(SPI1->STS_B.RXBNEF == 0)  {;}     ret = SPI1->DATA;
  while(SPI1->STS_B.TXBEF == 0)   {;}     SPI1->DATA = (uint16_t)0xFF;        //- отбросили первый байт
  while(SPI1->STS_B.RXBNEF == 0)  {;}     ret = SPI1->DATA;

  for(int i=0; i < sizeof(bma456_an_config_file); i++)
  {
    while(SPI1->STS_B.TXBEF == 0)   {;}     SPI1->DATA = (uint16_t)0xFF;      //- тактирование для чтения регистра
    while(SPI1->STS_B.RXBNEF == 0)  {;}     ret = SPI1->DATA;
//   bma_array[i] = ret;    //- для визуальной проверки в отладчике
    if(ret != bma456_an_config_file[i])   flag_err |= ERR_BMA456_ConfigFile;
  }
  while(SPI1->STS_B.BUSYF == 1)   {;}    CS_BMA456 = 1;
  for(int i=0; i<255; i++) {;}

  BMA456_WriteReg(INIT_CTRL, 0x01);   //- выйти из режима инициализации (доступа к файлу конфигурации в регистре FEATURES_IN)
  
  //- задержка не менее 140 мс (длительная!)
  for(int i=0; i<0x200000; i++)  {;}     //- до 255 -> 22мкс, 0x2000 -> 680мкс, для SYSCLK=72 МГц
 
  //- статус чипа после инициализации: 0x01 - успешно, ошибок нет
  ret = BMA456_ReadReg(INTERNAL_STATUS) & 0x0F;
//  while(ret != 0x01)  {;}
  if(ret == 0x00)    flag_err |= ERR_BMA456_NotInit;      //- чип не инициализирован
  if(ret == 0x02)    flag_err |= ERR_BMA456_ErrInit;      //- ошибка инициализации
  if(ret == 0x03)    flag_err |= ERR_BMA456_ErrDriver;    //- ошибка в файле конфигурации
  if(ret == 0x04)    flag_err |= ERR_BMA456_SnsStop;      //- сенсор остановлен

  //- настройка режима энергопотребления
  ret = BMA456_ReadReg(PWR_CONF);           //- performance mode
  BMA456_WriteReg(PWR_CONF, ret &= ~0x01);
  
  ret = BMA456_ReadReg(PWR_CTRL);           //- включение акселерометра
  BMA456_WriteReg(PWR_CTRL, ret |= 0x04);
  
  //- настройка акселерометра
  //- bit 7:      0 - averaging mode - режим усреднения
  //-             1 - continuous filter function - функция непрерывной фильтрации
  //- bits 6:4:   кол-во выборок для усреднения, или
  //-             настройка полосы пропускания
  //- bits 3:0:   скорость передачи данных
  
  BMA456_WriteReg(ACC_CONF, 0<<7 | 4<<4 | 0x06);
}


//------------------------------------------------------------------------------
//- чтение байта из регистра reg
//------------------------------------------------------------------------------
uint8_t BMA456_ReadReg(uint8_t reg)
{
  CS_BMA456 = 0;

  while(SPI1->STS_B.TXBEF == 0)   {;}     SPI1->DATA = reg | 0x80;        //- команда чтения регистра reg
  while(SPI1->STS_B.RXBNEF == 0)  {;}     ret = SPI1->DATA;
  while(SPI1->STS_B.TXBEF == 0)   {;}     SPI1->DATA = (uint16_t)0xFF;    //- отбросили первый байт
  while(SPI1->STS_B.RXBNEF == 0)  {;}     ret = SPI1->DATA;
  while(SPI1->STS_B.TXBEF == 0)   {;}     SPI1->DATA = (uint16_t)0xFF;    //- прочитали регистр
  while(SPI1->STS_B.RXBNEF == 0)  {;}     ret = SPI1->DATA;

  while(SPI1->STS_B.BUSYF == 1)   {;}    CS_BMA456 = 1;
  
  return ret;
}


void BMA456_Read_LSB_MSB(uint8_t reg, uint8_t *lsb, uint8_t *msb)
{
  CS_BMA456 = 0;

  while(SPI1->STS_B.TXBEF == 0)   {;}     SPI1->DATA = reg | 0x80;        //- отправили адрес регистра
  while(SPI1->STS_B.RXBNEF == 0)  {;}     ret = SPI1->DATA;
  while(SPI1->STS_B.TXBEF == 0)   {;}     SPI1->DATA = (uint16_t)0xFF;    //- отбросили первый байт
  while(SPI1->STS_B.RXBNEF == 0)  {;}     ret = SPI1->DATA;
  while(SPI1->STS_B.TXBEF == 0)   {;}     SPI1->DATA = (uint16_t)0xFF;    //- прочитали регистр
  while(SPI1->STS_B.RXBNEF == 0)  {;}     *lsb = SPI1->DATA;
  while(SPI1->STS_B.TXBEF == 0)   {;}     SPI1->DATA = (uint16_t)0xFF;    //- прочитали регистр
  while(SPI1->STS_B.RXBNEF == 0)  {;}     *msb = SPI1->DATA;

  while(SPI1->STS_B.BUSYF == 1)   {;}    CS_BMA456 = 1;
}

//------------------------------------------------------------------------------
//- запись байта в регистр reg
//------------------------------------------------------------------------------
void BMA456_WriteReg(uint8_t reg, uint8_t byte)
{
  CS_BMA456 = 0;

  while(SPI1->STS_B.TXBEF == 0)   {;}     SPI1->DATA = reg;               //- команда записи в регистр reg
  while(SPI1->STS_B.RXBNEF == 0)  {;}     ret = SPI1->DATA;
  while(SPI1->STS_B.TXBEF == 0)   {;}     SPI1->DATA = (uint16_t)byte;    //- данные в регистр
  while(SPI1->STS_B.RXBNEF == 0)  {;}     ret = SPI1->DATA;

  while(SPI1->STS_B.BUSYF == 1)   {;}    CS_BMA456 = 1;
}

